// Simulasi dampak stopword pada cosine similarity

function tokenize(text, useStopwords) {
  const STOP_WORDS = new Set([
    'a','an','the','is','are','was','were','be','been','being',
    'have','has','had','having','do','does','did','doing',
    'will','would','shall','should','may','might','must','can','could',
    'i','me','my','we','us','our','you','your','he','she','it','they','them',
    'this','that','these','those','here','there',
    'in','on','at','to','for','of','with','from','by','as',
    'and','or','not','but','if','so','than','then','also','just',
    'about','into','over','after','before','between','through',
    'am','an','no','up','out','all','any','each','every',
    'how','what','when','where','which','who','why',
  ])
  const words = text.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/)
    .filter(t => t.length > 1)
  const filtered = useStopwords ? words.filter(t => !STOP_WORDS.has(t)) : words
  const bigrams = []
  for (let i = 0; i < filtered.length - 1; i++) bigrams.push(filtered[i] + '_' + filtered[i+1])
  return [...filtered, ...bigrams]
}

function cosine(a, b) {
  const setA = new Set(a), setB = new Set(b)
  const all = new Set([...setA, ...setB])
  let dot = 0, magA = 0, magB = 0
  for (const t of all) {
    const cfA = a.filter(x => x === t).length
    const cfB = b.filter(x => x === t).length
    dot += cfA * cfB
    magA += cfA * cfA
    magB += cfB * cfB
  }
  return magA && magB ? dot / (Math.sqrt(magA) * Math.sqrt(magB)) : 0
}

const pairs = [
  ['How do I fix a type error in TypeScript?', 'How can I resolve a type error in TypeScript?'],
  ['How to delete a type error in TypeScript?', 'How do I remove a type error in TypeScript?'],
  ['Add dark mode support', 'Implement dark mode support'],
  ['fix type error', 'delete type error'],
  ['Create user authentication', 'Implement user authentication with JWT'],
  ['How to add a new API endpoint', 'How to create a new API endpoint'],
]

console.log('Query Pair Similarity: WITH vs WITHOUT stopwords')
console.log('')
for (const [a, b] of pairs) {
  const withStop = cosine(tokenize(a, true), tokenize(b, true))
  const withoutStop = cosine(tokenize(a, false), tokenize(b, false))
  const diff = (withStop - withoutStop).toFixed(4)
  console.log('Pair: ' + a)
  console.log('  vs: ' + b)
  console.log('  with stopwords:    ' + withStop.toFixed(4))
  console.log('  without stopwords: ' + withoutStop.toFixed(4))
  console.log('  difference:        ' + (diff > 0 ? '+' : '') + diff)
  console.log('')
}
